package com.aditya.chat.controller; import com.aditya.chat.dto.MessageRequest; import com.aditya.chat.entity.ChatMessage; import com.aditya.chat.service.MessageService; import jakarta.validation.Valid; import org.springframework.data.domain.Page; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/messages") public class MessageController{final MessageService s;public MessageController(MessageService s){this.s=s;}@GetMapping("/{chatId}")Page<ChatMessage> history(@PathVariable String chatId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){return s.history(chatId,page,size);}@PostMapping("/{chatId}")ChatMessage send(@PathVariable String chatId,@Valid @RequestBody MessageRequest r,Authentication a){return s.save(a.getName(),new MessageRequest(chatId,r.content()));}}
